{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d !== 0) return d
  }
  return x.length - y.length
}

const sortedKeys = (t) => [...t.map.keys()].sort(cmp)

function scalarJson(n) {
  if (n.t === 'string') return JSON.stringify(n.v)
  if (n.t === 'boolean') return n.v ? 'true' : 'false'
  if (n.t === 'integer') return n.v
  return JSON.stringify(n.v)
}

function emit(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${emit(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((i) => pad + emit(i, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return scalarJson(n)
}

export function toJson(root) {
  return emit(root, 0) + '\n'
}

export function toKeys(root) {
  const lines = []
  const walk = (n, path) => {
    lines.push(`${path} ${n.t}`)
    if (n.t === 'table') {
      for (const k of sortedKeys(n)) walk(n.map.get(k), `${path}.${k}`)
    } else if (n.t === 'array') {
      n.items.forEach((it, i) => walk(it, `${path}[${i}]`))
    }
  }
  for (const k of sortedKeys(root)) walk(root.map.get(k), k)
  return lines.map((l) => l + '\n').join('')
}
"}

