{"file_path":"src/parser.js","content":"const newTable = () => ({ t: 'table', map: new Map(), header: false })

class CfgError extends Error {}
const fail = (m) => {
  throw new CfgError(m)
}

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

const join = (p, k) => (p === '' ? k : `${p}.${k}`)

class Line {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  atEnd() {
    return this.i >= this.s.length || this.c === '#' || this.c === ';'
  }

  quoted(q) {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.s.length) fail('unterminated string')
      const ch = this.c
      if (ch === q) {
        this.i++
        return out
      }
      if (q === '"' && ch === '\\') {
        const e = this.s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          out += simple[e]
          this.i += 2
        } else if (e === 'u') {
          const h = this.s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          fail(`invalid escape \\${String.fromCodePoint(this.s.codePointAt(this.i + 1))}`)
        }
      } else {
        out += ch
        this.i++
      }
    }
  }

  name() {
    const c = this.c
    if (c === '"' || c === "'") return this.quoted(c)
    const st = this.i
    while (isBare(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }

  value(path) {
    this.ws()
    const c = this.c
    if (this.atEnd() || c === ',' || c === ']' || c === '}') fail('expected a value')
    if (c === '"' || c === "'") return { t: 'string', v: this.quoted(c) }
    if (c === '[') return this.array(path)
    if (c === '{') return this.inline(path)
    const st = this.i
    while (this.i < this.s.length && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
    if (INT.test(w)) {
      let d = w.replace(/_/g, '')
      const neg = d[0] === '-'
      d = d.replace(/^[+-]/, '').replace(/^0+(?=[0-9])/, '')
      return { t: 'integer', v: (neg && d !== '0' ? '-' : '') + d }
    }
    if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail(`invalid value ${w}`)
  }

  array(path) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      items.push(this.value(`${path}[${items.length}]`))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.c === ',') this.i++
      else if (this.c !== ']') fail('trailing text after a value')
    }
  }

  inline(path) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const parts = this.dotted()
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const full = parts.reduce(join, path)
      const v = this.value(full)
      assign(tbl, path, parts, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.c === ',') {
        this.i++
      } else if (this.c === '}') {
        this.i++
        return tbl
      } else fail('trailing text after a value')
    }
  }
}

// Table to descend into when a path walks through `n`, or null.
function through(n) {
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  return null
}

function assign(tbl, base, parts, v) {
  let cur = tbl
  let path = base
  for (let i = 0; i < parts.length - 1; i++) {
    path = join(path, parts[i])
    let n = cur.map.get(parts[i])
    if (!n) {
      n = newTable()
      cur.map.set(parts[i], n)
    }
    const t = through(n)
    if (!t) fail(`${path} is not a table`)
    cur = t
  }
  const k = parts[parts.length - 1]
  path = join(path, k)
  if (cur.map.has(k)) fail(`key ${path} is defined twice`)
  cur.map.set(k, v)
}

function header(root, L) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  L.ws()
  const parts = L.dotted()
  L.ws()
  const close = aot ? ']]' : ']'
  if (L.s.startsWith(close, L.i)) L.i += close.length
  else fail('unterminated table header')
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')

  let cur = root
  let path = ''
  for (let i = 0; i < parts.length - 1; i++) {
    path = join(path, parts[i])
    let n = cur.map.get(parts[i])
    if (!n) {
      n = newTable()
      cur.map.set(parts[i], n)
    }
    const t = through(n)
    if (!t) fail(`${path} is not a table`)
    cur = t
  }
  const k = parts[parts.length - 1]
  path = join(path, k)
  const n = cur.map.get(k)
  if (aot) {
    if (!n) {
      const t = newTable()
      cur.map.set(k, { t: 'array', items: [t], aot: true })
      return t
    }
    if (n.t !== 'array' || !n.aot) fail(`${path} is not an array of tables`)
    const t = newTable()
    n.items.push(t)
    return t
  }
  if (!n) {
    const t = newTable()
    t.header = true
    cur.map.set(k, t)
    return t
  }
  if (n.t !== 'table') fail(`${path} is not a table`)
  if (n.header) fail(`table ${path} is defined twice`)
  n.header = true
  return n
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const L = new Line(lines[ln])
      L.ws()
      if (L.i >= L.s.length || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        // track path of the current table for key paths
        cur = header(root, L)
        curPath = pathOf(root, cur)
        continue
      }
      const parts = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value(parts.reduce(join, curPath))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, parts, v)
    } catch (e) {
      if (e instanceof CfgError) {
        e.cfgLine = ln + 1
      }
      throw e
    }
  }
  return root
}

function pathOf(root, target) {
  const find = (n, p) => {
    if (n === target) return p
    const kids = n.t === 'table' ? [...n.map].map(([k, c]) => [k, c]) : []
    for (const [k, c] of kids) {
      const q = join(p, k)
      const t = through(c)
      if (t) {
        if (c.t === 'array') {
          // only the last element can be current
          const r = find(t, q)
          if (r !== null) return r
        } else {
          const r = find(t, q)
          if (r !== null) return r
        }
      }
    }
    return null
  }
  return find(root, '')
}
"}

