  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  return null
}

function assign(tbl, base, parts, v) {
  let cur = tbl
  let path = base
  for (let i = 0; i < parts.length - 1; i++) {
    path = join(path, parts[i])
    let n = cur.map.get(parts[i])
    if (!n) {
      n = newTable()
      cur.map.set(parts[i], n)
    }
    const t = through(n)
    if (!t) fail(`${path} is not a table`)
    cur = t
  }
  const k = parts[parts.length - 1]
  path = join(path, k)
  if (cur.map.has(k)) fail(`key ${path} is defined twice`)
  cur.map.set(k, v)
}

function header(root, L) {
  L.i++
  const aot = L.c === '['
  if (aot) L.i++
  L.ws()
  const parts = L.dotted()
  L.ws()
  const close = aot ? ']]' : ']'
  if (L.s.startsWith(close, L.i)) L.i += close.length
  else fail('unterminated table header')
  L.ws()
  if (!L.atEnd()) fail('trailing text after a table header')

  let cur = root
  let path = ''
  for (let i = 0; i < parts.length - 1; i++) {
    path = join(path, parts[i])
    let n = cur.map.get(parts[i])
    if (!n) {
      n = newTable()
      cur.map.set(parts[i], n)
    }
    const t = through(n)
    if (!t) fail(`${path} is not a table`)
    cur = t
  }
  const k = parts[parts.length - 1]
  path = join(path, k)
  const n = cur.map.get(k)
  if (aot) {
    if (!n) {
      const t = newTable()
      cur.map.set(k, { t: 'array', items: [t], aot: true })
      return t
    }
    if (n.t !== 'array' || !n.aot) fail(`${path} is not an array of tables`)
    const t = newTable()
    n.items.push(t)
    return t
  }
  if (!n) {
    const t = newTable()
    t.header = true
    cur.map.set(k, t)
    return t
  }
  if (n.t !== 'table') fail(`${path} is not a table`)
  if (n.header) fail(`table ${path} is defined twice`)
  n.header = true
  return n
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = ''
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const L = new Line(lines[ln])
      L.ws()
      if (L.i >= L.s.length || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        // track path of the current table for key paths
        cur = header(root, L)
        curPath = pathOf(root, cur)
        continue
      }
      const parts = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value(parts.reduce(join, curPath))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, parts, v)
    } catch (e) {
      if (e instanceof CfgError) {
        e.cfgLine = ln + 1
      }
      throw e
    }
  }
  return root
}

function pathOf(root, target) {
  const find = (n, p) => {
    if (n === target) return p
    const kids = n.t === 'table' ? [...n.map].map(([k, c]) => [k, c]) : []
    for (const [k, c] of kids) {
      const q = join(p, k)
      const t = through(c)
      if (t) {
        if (c.t === 'array') {
          // only the last element can be current
          const r = find(t, q)
          if (r !== null) return r
        } else {
          const r = find(t, q)
          if (r !== null) return r
        }
      }
    }
    return null
  }
  return find(root, '')
}
"}

